TLM.f("Tempora/Pasc7-5",{"officium":"Feria Sexta Quattuor temporum Pentecostes","rule":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"ruleInherited":["Gloria","Sequentia","Credo","Prefatio=Spiritu=hodierna die;"],"fallback":"Tempora/Pasc7-0","sections":{"Introitus":[{"k":"ref","la":"Ps 70:8 70:23"},{"k":"text","la":"Repleátur os meum laude tua, allelúja: ut possim cantáre, allelúja: gaudébunt lábia mea, dum cantávero tibi, allelúja, allelúja."},{"k":"ref","la":"Ps 70:1-2"},{"k":"text","la":"In te, Dómine, sperávi, non confúndar in ætérnum: in justítia tua líbera me et éripe me."},{"k":"macro","name":"Gloria"},{"k":"text","la":"Repleátur os meum laude tua, allelúja: ut possim cantáre, allelúja: gaudébunt lábia mea, dum cantávero tibi, allelúja, allelúja."}],"Oratio":[{"k":"text","la":"Da, quǽsumus, Ecclésiæ tuæ, miséricors Deus: ut, Sancto Spíritu congregáta, hostíli nullátenus incursióne turbétur."},{"k":"macro","name":"Per Dominum eiusdem"}],"Lectio":[{"k":"text","la":"Léctio Joélis Prophétæ"},{"k":"ref","la":"Joël 2:23-24; 2:26-27"},{"k":"text","la":"Hæc dicit Dóminus Deus: Exsultáte, fílii Sion, et lætámini in Dómino, Deo vestro: quia dedit vobis doctórem justítiæ, et descéndere fáciet ad vos imbrem matutínum et serótinum, sicut in princípio. Et implebúntur áreæ fruménto et redundábunt torculária vino et óleo. Et comedétis vescéntes et saturabímini, et laudábitis nomen Dómini, Dei vestri, qui fecit mirabília vobíscum: et non confundétur pópulus meus in sempitérnum. Et sciétis, quia in médio Israël ego sum: et ego Dóminus, Deus vester, et non est ámplius: et non confundétur pópulus meus in ætérnum: ait Dóminus omnípotens."}],"Graduale":[{"k":"text","la":"Allelúja, allelúja."},{"k":"ref","la":"Ps 12:1"},{"k":"text","la":"O quam bonus et suávis est, Dómine, Spíritus tuus in nobis! Allelúja. (Hic genuflectitur)"},{"k":"text","la":"Veni, Sancte Spíritus, reple tuórum corda fidélium: et tui amóris in eis ignem accénde.","mark":"V"}],"Sequentia":[{"k":"text","la":"Veni, Sancte Spíritus,"},{"k":"text","la":"et emítte cǽlitus"},{"k":"text","la":"lucis tuæ rádium."},{"k":"sep"},{"k":"text","la":"Veni, pater páuperum;"},{"k":"text","la":"veni, dator múnerum;"},{"k":"text","la":"veni, lumen córdium."},{"k":"sep"},{"k":"text","la":"Consolátor óptime,"},{"k":"text","la":"dulcis hospes ánimæ,"},{"k":"text","la":"dulce refrigérium."},{"k":"sep"},{"k":"text","la":"In labóre réquies,"},{"k":"text","la":"in æstu tempéries,"},{"k":"text","la":"in fletu solácium."},{"k":"sep"},{"k":"text","la":"O lux beatíssima,"},{"k":"text","la":"reple cordis íntima"},{"k":"text","la":"tuórum fidélium."},{"k":"sep"},{"k":"text","la":"Sine tuo númine"},{"k":"text","la":"nihil est in hómine,"},{"k":"text","la":"nihil est innóxium."},{"k":"sep"},{"k":"text","la":"Lava quod est sórdidum,"},{"k":"text","la":"riga quod est áridum,"},{"k":"text","la":"sana quod est sáucium."},{"k":"sep"},{"k":"text","la":"Flecte quod est rígidum,"},{"k":"text","la":"fove quod est frígidum,"},{"k":"text","la":"rege quod est dévium."},{"k":"sep"},{"k":"text","la":"Da tuis fidélibus,"},{"k":"text","la":"in te confidéntibus,"},{"k":"text","la":"sacrum septenárium."},{"k":"sep"},{"k":"text","la":"Da virtútis méritum,"},{"k":"text","la":"da salútis éxitum,"},{"k":"text","la":"da perénne gáudium."},{"k":"text","la":"Amen. Allelúja."}],"Evangelium":[{"k":"text","la":"Sequéntia ✠ sancti Evangélii secúndum Lucam"},{"k":"ref","la":"Luc 5:17-26"},{"k":"text","la":"In illo témpore: Factum est in una diérum, et Jesus sedébat docens. Et erant pharisǽi sedéntes, et legis doctóres, qui vénerant ex omni castéllo Galilǽæ et Judǽæ et Jerúsalem: et virtus Dómini erat ad sanándum eos. Et ecce, viri portántes in lecto hóminem, qui erat paralýticus: et quærébant eum inférre, et pónere ante eum. Et non inveniéntes, qua parte illum inférrent præ turba, ascendérunt supra tectum, et per tégulas summisérunt eum cum lecto in médium ante Jesum. Quorum fidem ut vidit, dixit: Homo, remittúntur tibi peccáta tua. Et cœpérunt cogitáre scribæ et pharisǽi, dicéntes: Quis est hic, qui lóquitur blasphémias ? Quis potest dimíttere peccáta nisi solus Deus? Ut cognóvit autem Jesus cogitatiónes eórum, respóndens dixit ad illos: Quid cogitátis in córdibus vestris? Quid est facílius dícere: Dimittúntur tibi peccáta, an dícere: Surge et ámbula? Ut autem sciátis, quia Fílius hóminis habet potestátem in terra dimitténdi peccáta, ait paralýtico: Tibi dico, surge, tolle lectum tuum et vade in domum tuam. Et conféstim consúrgens coram illis, tulit lectum, in quo jacébat: et ábiit in domum suam, magníficans Deum. Et stupor apprehéndit omnes et magnificábant Deum. Et repléti sunt timóre, dicéntes: Quia vídimus mirabília hódie."}],"Offertorium":[{"k":"ref","la":"Ps 145:2"},{"k":"text","la":"Lauda, ánima mea, Dóminum: laudábo Dóminum in vita mea: psallam Deo meo, quámdiu ero, allelúja."}],"Secreta":[{"k":"text","la":"Sacrifícia, Dómine, tuis obláta conspéctibus, ignis ille divínus absúmat, qui discipulórum Christi, Fílii tui, per Spíritum Sanctum corda succéndit."},{"k":"macro","name":"Per Dominum eiusdem"}],"Communio":[{"k":"ref","la":"Joannes 14:18"},{"k":"text","la":"Non vos relínquam órphanos: véniam ad vos íterum, allelúja: et gaudébit cor vestrum, allelúja."}],"Postcommunio":[{"k":"text","la":"Súmpsimus, Dómine, sacri dona mystérii: humíliter deprecántes; ut, quæ in tui commemoratiónem nos fácere præcepísti, in nostræ profíciant infirmitátis auxílium:"},{"k":"macro","name":"Qui vivis"}]},"hr":{"293f7d4539729433":{"t":"Ps 70, 8 i 23, Ps 70, 1-2\n(Ps 70, 8 i 23) Neka se napune usta moja hvalom tvojom, <i>aleluja</i>,\nda mogu pjevati, <i>aleluja</i>!\nKliktat će od radosti usne moje dok ti budem pjevao, <i>aleluja</i>, <i>aleluja</i>.\n(Ps 70, 1-2) U te se, Gospodine, uzdam, neću se postidjeli dovijeka. U pravdi me svojoj oslobodi i izbavi!\n<i>Slava Ocu, i Sinu, i Duhu Svetomu. Kako bijaše na početku, tako i sada i vazda i u vijeke vjekova. Amen</i>.\n(Ps 70, 8 i 23) Neka se napune usta moja hvalom tvojom, <i>aleluja</i>,\nda mogu pjevati, <i>aleluja</i>!\nKliktat će od radosti usne moje dok ti budem pjevao, <i>aleluja</i>, <i>aleluja</i>.","kn":"(Ps. 70, 8, 23). Napunila se hvale Tvoje usta moja, aleluja, da mogu pjevati, aleluja; Tebi da pjevaju usta moja, aleluja, aleluja. (Ps. 70, 1, 2). U Te se. Gospodine, uzdam, ne ću se postidjeti dovijeka; u pravdi me svojoj oslobodi i izbavi! Slava Ocu . . . Napunila se . . , <i>aleluja</i>, <i>aleluja</i>.","knRef":"Kniewald 1942, str. 352–353 (snimka 177) (OCR)"},"53655a18ed911803":{"t":"<i>Pomolimo se</i>.\nPodaj, molimo, milosrdni Bože, da nikakva neprijateljska navala ne smete tvoju Crkvu sakupljenu Duhom Svetim.\n<i>Po Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Podaj, molimo, milosrdni Bože, da ni- - kakva neprijateljska navela ne smete Crkvu Tvoju, sakupljenu Duhom Svetim, ipo G. n. , . . u jedinstvu istoga Duha . . .","knRef":"Kniewald 1942, str. 352–353 (snimka 177) (OCR)"},"38783f1045f1dff6":{"t":"Jl 2, 23-24 et 26-27\nČitanje Joela proroka. Ovo govori Gospodin Bog: Radujte se, sinovi Sionski, i veselite se u Gospodinu Bogu svojemu, jer vam dade naučitelja pravde i spustit će vam dažd rani i kasni kao u početku. I gumna će se napuniti žita, a tijesci vaši prelijevat će se vinom i uljem. I jest ćete izobilja i nasitit ćete se i hvalit ćete ime Gospodina Boga svojega koji je učinio za vas divnih stvari. I puk moj neće se smesti dovijeka. I poznat ćete da sam ja usred Izraela. I da sam ja Gospodin Bog vaš i da nemate drugoga. I puk moj neće se smesti dovijeka, govori Gospodin svemogući.","kn":"Čitanje Joela Proroka (2. 23-27). Ovo govori Gospodin Bog: Radujte se, sinovi Sionski, 1 veselite se Gospodinu Bogu svojemu: jer vam dade naučitelja pravde, i spustit će vam dažd rani i kasni, kao u početku. I gumna će se napuniti žita, a tijesci vaši prelijevat će se vinom i uljem. I jesti ćete izobilja, i nasitit ćete se, i hvalit ćete ime Gospodina Boga svojega, koji je učinio za vas divnih stvari: i puk moj ne će se smesti do vijeka. I poznat ćete, da sam ja usred Izraela: i da sam ja Gospodin Bog vaš, i da nema drugoga: i p.uk moj ne će se smesti do vijeka: govori Gospodin svemogući.","knRef":"Kniewald 1942, str. 352–353 (snimka 177) (OCR)"},"91638148e9b68ca4":{"t":"Mudr 12, 1\n<i>Aleluja</i>, <i>aleluja</i>.\nO kako je dobar i sladak, Gospodine, Duh tvoj u nama, <i>aleluja</i>.\n[Ovdje se poklekne] Dođi, Duše Sveti, napuni srca svojih vjernih i zapali u njima oganj svoje ljubavi.","kn":"Aleluja, aleluja (Mudr. 12, 1). O, kako je dobar i sladak. Gospodine, Duh Tvoj u nama, aleluja. (Ovdje se poklekne.) Dođi, Duše Sveti, napuni srca svojih vjernih i zapali u njima oganj ljubavi svoje.","knRef":"Kniewald 1942, str. 352–353 (snimka 177) (OCR)"},"8986d237bd5894a0":{"t":"Dođi, duše presveti, /Sa neba nas posjeti /Zrakom svoje milosti. <i>\n</i>\nDođi, Oče ubogih,/Djelitelju dara svih,/Dođi, srca svjetlosti. <i>\n</i>\nTješitelju tako blag, /Ti nebeski Goste drag, /Pun miline hlade tih. <i>\n</i>\nUmornima odmore,/U vrućini lahore,/Razgovore žalosnih. <i>\n</i>\nSjaju svjetla blaženog,/Sjaj u srcu puka svog,/Napuni nam dušu svu. <i>\n</i>\nBez božanstva tvojega /Svi smo mi bez ičega,/Tonemo u crnom zlu. <i>\n</i>\nNečiste nas umivaj,/Suha srca zalivaj, /Vidaj rane ranjenim. <i>\n</i>\nMekšaj ćudi kamene,/ Zagrij grudi ledene,/Ne daj nama putem zlim. <i>\n</i>\nSvim što vjeru imaju,/Što se u te ufaju, /Sedam svojih dara daj. <i>\n</i>\nDaj nam krepost zaslužnu/I smrt lijepu, blaženu,/Daj vjekovit svima raj. <i>\n</i>\n<i>amen</i>, <i>aleluja</i>."},"fd892a3934892ad1":{"t":"Lk 5, 17-26\nSlijedi sveto Evanđelje po Luki. U ono vrijeme, kad je Isus jedan dan učio, sjedili su farizeji i književnici, koji su došli iz svih sela galilejskih i judejskih i iz Jeruzalema, i sila Gospodnja bila je u njemu da liječi. I gle, ljudi donesoše na postelji čovjeka koji je bio uzet i tražili su da ga unesu i postave pred njega. I ne našavši kuda će ga unijeti od naroda, popeše se na krov i kroz otvor od ploča spustiše ga s posteljom na sredinu pred Isusa. Kad je Isus vidio njihovu vjeru, reče: Čovječe, oprošteni su ti tvoji grijesi. Tada počeše pomišljati književnici i farizeji govoreći: Tko je ovaj, što huli na Boga? A kad Isus razabra njihove misli reče im: Što razmišljate u svojim srcima? Što je lakše reći: Oprošteni su ti tvoji grijesi, ili reći: Ustani i hodi? Nego da znate, da Sin čovječji ima vlast na zemlji opraštati grijehe, reče uzetome: Tebi govorim, ustani, uzmi svoju postelju i idi kući svojoj! I odmah ustavši pred njima uze postelju na kojoj je ležao i otiđe svojoj kući slaveći Boga. I sve obuze udivljenje i stanu slaviti Boga i napunivši se straha stanu govoriti: Danas se nagledasmo čudesa!","kn":"t Slijedi sv. evanđelje po Luki (5, 17-26). U ono vrijeme, kad je Isus jedan dan učio, sjedili su farizeji 1 književnici, koji su došli iz svih sela Galilejskih i Judejskih 1 iz Jeruzalema, 1 sUa Gospodnja bila je u njemu, da liječi. I gle, ljudi donesoše na postelji čovjeka, koji je bio uzet i tražili su, da ga unesu i postave pred njega. I ne naišavši, kuda će ga unijeti od naroda, popeše se na krov i kroz otvor od ploča spustiše ga s posteljom na sredinu pred Isusa. Kad je Isus vidio njihovu vjeru, reče; Cpvječe, oprošteni su ti grijesi tvoji. Tada počeše pomišljati književnici i farizeji govoreći: Tko je ovaj, što ihuli na Boga? A kad Isus razabra njihove misli, reče im: Sto razmišljate u srcima svojim? Što je lakše reći: Oprošteni su ti grijesi tvoji, ili reći: Ustani i hodi? Nego da znate, da Sin čovječji ima vlast na zemlji opraštati grijehe, reče uzetomu: Tebi govorim, ustani, uzmi svoju postelju, i idi kući svojoj! I odmah ustavŠi pred injima uze postelju, na kojoj je ležao, i otide svojoj kući slaveći Boga. I sve obuze udivljenje i stanu slaviti Boga i napunivši se straha stanu govoriti: Danas se nagledasmo čuda!","knRef":"Kniewald 1942, str. 352–353 (snimka 177) (OCR)"},"0f89e89f1130bcea":{"t":"Ps 145, 2\nHvali, dušo moja, Gospodina! Hvalit ću Gospodina za života svojega! Pjevat ću Bogu svojemu dok me bude, <i>aleluja</i>.","kn":"(Ps. 145, 2). Hvali, dušo moja. Gospodina; hvalit ĆU Gospodina za života svojega, psalme ću pjevati Bogu svojemu, dok me bude, aleluja.","knRef":"Kniewald 1942, str. 324–325 (snimka 163) (OCR)"},"32ff328155a587ea":{"t":"Prožeo, Gospodine, ove žrtve tebi prikazane onaj božanski oganj koji je po Duhu Svetom zapalio srca učenika Krista, Sina Tvoga.\n<i>Po istom Gospodinu našemu Isusu Kristu, Sinu tvome: Koji s tobom živi i kraljuje u jedinstvu istog Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Pnožeo, Gospodine, ove žrtve, Tebi prikazane, onaj božan.ski oganj, koji je po Duhu Svetom zapalio srca učenika Krista, Sina Tvoga, koji s Tobom živi i kraljuje u jedinstvu istoga Duha","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"e36be14714c3ff04":{"t":"Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo tebi, Gospodine, sveti Oče, svemogući vječni Bože, po Kristu Gospodinu našemu. On uziđe nad sva nebesa, sjede uz tvoju desnu, te obećanog Duha Svetoga na današnji dan izli na posinjenu djecu. – Stoga sav svijet na krugu zemaljskom kliče zanosnom radošću, a i višnje sile i s njima anđeoske vlasti zajedno pjevaju pjesmu tvoje slave govoreći bez prestanka:","kn":"Predslovlje: Uistinu je dostojno i pravedno, pravo i spasonosno, da vazda i svagdje zahvaljujemo Tebi. Gospodine sveti. Oče svemogući, vječni Bože, po Kristu, Gospodinu našem, koji je uzašao nad sva nebesa i sjeo s desne Tvoje i na današnji dan izlio obećanoga Duha Svetoga na Božje posinke. Zato kliče čitav svijet i svemir pun veselja. A i višnje moći i anđeoske vlasti pjevaju pjesmu Tvoje slave govoreći bez prestanka:","knRef":"Kniewald 1942, str. 344–345 (snimka 173) (OCR)"},"9a4ebb8fe0624b7d":{"t":"Io 14, 18\nNeću vas ostaviti sirote. Opet ću doći k vama, <i>aleluja</i>,\ni radovat će se srce vaše, <i>aleluja</i>.","kn":"(Iv. 14, 18). Ne ću vas ostaviti sirote, opet ću doći k vama, aleluja, i radovat će se srce vaše, aleluja.","knRef":"Kniewald 1942, str. 354–355 (snimka 178) (OCR)"},"33ce546681338107":{"t":"<i>Pomolimo se</i>.\nPrimili smo, Gospodine, darove svetog otajstva i smjerno te molimo da bude na pomoć našoj slabosti ono što si zapovjedio da činimo tebi na spomen:\n<i>koji živiš i kraljuješ s Bogom Ocem u jedinstvu Duha Svetoga, Bog: po sve vijeke vjekova</i>.","kn":"Prinusmo, Gospođine, darove svetoga otajstva, smjerno moleći, da bude korisna pomoć našoj slabosti, što si zapovjedio, da. činimo na Tvoj spomen, koji živiš i kraljuješ...","knRef":"Kniewald 1942, str. 430–431 (snimka 216) (OCR)"}}});
